 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static void Refused(Action operation){bool refused=false;try{operation();}catch(InvalidOperationException){refused=true;}Check(refused,"Generated invalid identity, proof, history or SCM was accepted");}
 static byte[] Envelope(bool generic=false){
  var options=new CngKeyCreationParameters{ExportPolicy=CngExportPolicies.AllowExport|CngExportPolicies.AllowPlaintextExport};byte[] secret=null,blob=null,plain=null,cipher=null,privateBlob=null;
  try{using(var key=CngKey.Create(generic?CngAlgorithm.ECDiffieHellmanP256:CngAlgorithm.ECDsaP256,null,options)){
   privateBlob=key.Export(CngKeyBlobFormat.EccPrivateBlob);blob=key.Export(CngKeyBlobFormat.EccPublicBlob);byte[] raw=new byte[65];raw[0]=4;Array.Copy(blob,8,raw,1,64);string pub=BitConverter.ToString(raw).Replace("-","").ToLowerInvariant();
   // Canonical SEC1-in-PKCS8 as exported by Node/OpenSSL. CNG's native
   // PKCS8 export can instead contain its legacy raw-scalar payload.
   byte[] prefix={0x30,0x81,0x87,2,1,0,0x30,0x13,6,7,0x2a,0x86,0x48,0xce,0x3d,2,1,6,8,0x2a,0x86,0x48,0xce,0x3d,3,1,7,4,0x6d,0x30,0x6b,2,1,1,4,0x20};secret=new byte[138];Array.Copy(prefix,secret,prefix.Length);Array.Copy(privateBlob,72,secret,36,32);byte[] pointHeader={0xa1,0x44,3,0x42,0};Array.Copy(pointHeader,0,secret,68,5);Array.Copy(raw,0,secret,73,65);
   plain=R.Encode(new SortedDictionary<string,object>{{"version",1},{"required",false},{"publicKey",pub},{"secret",Convert.ToBase64String(secret)},{"peers",new object[0]}});
   cipher=ProtectedData.Protect(plain,Encoding.UTF8.GetBytes("Sodashitsu desktop endpoint identity v1"),DataProtectionScope.CurrentUser);
   return R.Encode(new SortedDictionary<string,object>{{"version",1},{"mode","dpapi-user"},{"data",Convert.ToBase64String(cipher)}});
  }}finally{foreach(var b in new[]{secret,blob,plain,cipher,privateBlob})if(b!=null)Array.Clear(b,0,b.Length);}
 }
 static byte[] Decrypt(byte[] cipher){return ProtectedData.Unprotect(cipher,Encoding.UTF8.GetBytes("Sodashitsu desktop endpoint identity v1"),DataProtectionScope.CurrentUser);}
 public static void Run(){
  Check(SodaDesktopSigninClaimedInitializeRecovery.TicketArgument("inspect",null)&&SodaDesktopSigninClaimedInitializeRecovery.TicketArgument("inspect",string.Empty)&&SodaDesktopSigninClaimedInitializeRecovery.TicketArgument("bind",string.Empty),"PowerShell absent ticket was rejected");
  Check(!SodaDesktopSigninClaimedInitializeRecovery.TicketArgument("inspect",new string('a',64))&&!SodaDesktopSigninClaimedInitializeRecovery.TicketArgument("recover",string.Empty)&&!SodaDesktopSigninClaimedInitializeRecovery.TicketArgument("bind"," "),"Unexpected ticket argument was accepted");
