    var vault=P.Parse(plain,65536);if(mode=="required")vault["required"]=true;if(mode=="peers")vault["peers"]=new object[]{new Dictionary<string,object>{{"role","viewer"}}};if(mode=="version")vault["version"]="1";if(mode=="public")vault["publicKey"]="04"+new string('0',128);if(mode=="secret")vault["secret"]="AA==";if(mode.StartsWith("der-",StringComparison.Ordinal)){byte[] key=Convert.FromBase64String((string)vault["secret"]),derModified=null;try{derModified=(byte[])key.Clone();if(mode=="der-curve")derModified[26]=8;if(mode=="der-version")derModified[5]=1;if(mode=="der-trailing"){derModified=new byte[key.Length+1];Array.Copy(key,derModified,key.Length);}if(mode=="der-nonminimal"){derModified=new byte[key.Length+1];derModified[0]=0x30;derModified[1]=0x82;derModified[2]=0;derModified[3]=0x87;Array.Copy(key,3,derModified,4,key.Length-3);}vault["secret"]=Convert.ToBase64String(derModified);}finally{Array.Clear(key,0,key.Length);if(derModified!=null)Array.Clear(derModified,0,derModified.Length);}}
    if(mode=="negated-public"){
     string pub=(string)vault["publicKey"];byte[] raw=new byte[65];for(int i=0;i<65;i++)raw[i]=Convert.ToByte(pub.Substring(i*2,2),16);byte[] neg=(byte[])raw.Clone();string prime="ffffffff00000001000000000000000000000000ffffffffffffffffffffffff";int borrow=0;for(int i=31;i>=0;i--){int d=Convert.ToByte(prime.Substring(i*2,2),16)-raw[i+33]-borrow;borrow=d<0?1:0;neg[i+33]=(byte)(d<0?d+256:d);}byte[] key=Convert.FromBase64String((string)vault["secret"]);try{for(int i=0;i<=key.Length-65;i++)if(raw.SequenceEqual(key.Skip(i).Take(65)))Array.Copy(neg,0,key,i,65);vault["secret"]=Convert.ToBase64String(key);vault["publicKey"]=BitConverter.ToString(neg).Replace("-","").ToLowerInvariant();}finally{Array.Clear(key,0,key.Length);Array.Clear(raw,0,raw.Length);Array.Clear(neg,0,neg.Length);}
    }
    byte[] changed=R.Encode(vault),encrypted=ProtectedData.Protect(changed,Encoding.UTF8.GetBytes("Sodashitsu desktop endpoint identity v1"),DataProtectionScope.CurrentUser);try{outer["data"]=Convert.ToBase64String(encrypted);Refused(()=>P.ValidateIdentity(R.Encode(outer),Decrypt));}finally{Array.Clear(changed,0,changed.Length);Array.Clear(encrypted,0,encrypted.Length);}
   }finally{Array.Clear(cipher,0,cipher.Length);Array.Clear(plain,0,plain.Length);}
  }
  foreach(string failure in new string[]{null,"runs-archived","admin-archived","new-directories","initial-written","receipt-written"})Fixture(valid,fp,failure);
  Array.Clear(valid,0,valid.Length);Console.WriteLine("claimed_initialize_generated_identity_proofs_restart_archives_and_interruptions_passed");
 }
 public static string ValidateGeneratedNodeFile(string path){byte[] bytes=File.ReadAllBytes(path);try{return P.ValidateIdentity(bytes,Decrypt);}finally{Array.Clear(bytes,0,bytes.Length);}}
